  function toUnit(latDeg, lonDeg) {
    const p = latDeg * Math.PI / 180;
    const l = lonDeg * Math.PI / 180;
    const cp = Math.cos(p);
    return [cp * Math.sin(l), Math.sin(p), cp * Math.cos(l)];
  }

